(function () {
  function normGroups(groups) {
    return groups.map(function (g) {
      return {
        amount: g.amount,
        claimIds: g.claimIds.slice().sort(),
        patientRef: g.patientRef,
        procedureCode: g.procedureCode,
        serviceDate: g.serviceDate
      };
    }).sort(function (a, b) {
      var ka = a.patientRef + '|' + a.serviceDate + '|' + a.procedureCode + '|' + a.amount + '|' + a.claimIds.join(',');
      var kb = b.patientRef + '|' + b.serviceDate + '|' + b.procedureCode + '|' + b.amount + '|' + b.claimIds.join(',');
      if (ka < kb) return -1;
      if (ka > kb) return 1;
      return 0;
    });
  }

  function expectGroups(actual, expectedGroups) {
    assert.deepEqual(Object.keys(actual).sort(), ['groups']);
    assert.equal(actual.groups.length, expectedGroups.length);
    var i;
    for (i = 0; i < actual.groups.length; i = i + 1) {
      assert.deepEqual(Object.keys(actual.groups[i]).sort(), ['amount', 'claimIds', 'patientRef', 'procedureCode', 'serviceDate']);
      assert.ok(Array.isArray(actual.groups[i].claimIds));
      assert.ok(actual.groups[i].claimIds.length >= 2);
    }
    assert.deepEqual(normGroups(actual.groups), normGroups(expectedGroups));
  }

  test('flags both claims when the four compared fields match even if claim ids differ', function () {
    var batch = [
      { claimId: 'C-1', patientRef: 'P-001', serviceDate: '2024-03-05', procedureCode: '99213', amount: 120.00 },
      { claimId: 'C-2', patientRef: 'P-001', serviceDate: '2024-03-05', procedureCode: '99213', amount: 120.00 }
    ];
    var before = [
      { claimId: 'C-1', patientRef: 'P-001', serviceDate: '2024-03-05', procedureCode: '99213', amount: 120.00 },
      { claimId: 'C-2', patientRef: 'P-001', serviceDate: '2024-03-05', procedureCode: '99213', amount: 120.00 }
    ];
    var result = code.findDuplicateGroups(batch);
    assert.equal(batch.length, 2);
    assert.deepEqual(batch[0], before[0]);
    assert.deepEqual(batch[1], before[1]);
    expectGroups(result, [
      { claimIds: ['C-1', 'C-2'], patientRef: 'P-001', serviceDate: '2024-03-05', procedureCode: '99213', amount: 120.00 }
    ]);
  });

  test('does not flag either claim when the amount is 125.00 instead of 120.00', function () {
    var result = code.findDuplicateGroups([
      { claimId: 'C-3', patientRef: 'P-002', serviceDate: '2024-03-05', procedureCode: '99213', amount: 120.00 },
      { claimId: 'C-4', patientRef: 'P-002', serviceDate: '2024-03-05', procedureCode: '99213', amount: 125.00 }
    ]);
    assert.deepEqual(result, { groups: [] });
  });

  test('returns one group of three claims rather than three pair groups', function () {
    var result = code.findDuplicateGroups([
      { claimId: 'C-5', patientRef: 'P-003', serviceDate: '2024-03-06', procedureCode: '99214', amount: 80.00 },
      { claimId: 'C-6', patientRef: 'P-003', serviceDate: '2024-03-06', procedureCode: '99214', amount: 80.00 },
      { claimId: 'C-7', patientRef: 'P-003', serviceDate: '2024-03-06', procedureCode: '99214', amount: 80.00 }
    ]);
    expectGroups(result, [
      { claimIds: ['C-5', 'C-6', 'C-7'], patientRef: 'P-003', serviceDate: '2024-03-06', procedureCode: '99214', amount: 80.00 }
    ]);
  });

  test('returns no group for a single claim and does not compare a second batch', function () {
    var first = code.findDuplicateGroups([
      { claimId: 'C-8', patientRef: 'P-004', serviceDate: '2024-03-07', procedureCode: '99213', amount: 120.00 }
    ]);
    var second = code.findDuplicateGroups([
      { claimId: 'C-9', patientRef: 'P-004', serviceDate: '2024-03-07', procedureCode: '99213', amount: 120.00 }
    ]);
    assert.deepEqual(first, { groups: [] });
    assert.deepEqual(second, { groups: [] });
  });

  test('lists only the three matching claim ids and omits the two unmatched claims', function () {
    var result = code.findDuplicateGroups([
      { claimId: 'M-1', patientRef: 'P-010', serviceDate: '2024-04-15', procedureCode: '99213', amount: 55.50 },
      { claimId: 'U-1', patientRef: 'P-011', serviceDate: '2024-04-15', procedureCode: '99213', amount: 55.50 },
      { claimId: 'M-2', patientRef: 'P-010', serviceDate: '2024-04-15', procedureCode: '99213', amount: 55.50 },
      { claimId: 'U-2', patientRef: 'P-010', serviceDate: '2024-04-16', procedureCode: '99213', amount: 55.50 },
      { claimId: 'M-3', patientRef: 'P-010', serviceDate: '2024-04-15', procedureCode: '99213', amount: 55.50 }
    ]);
    expectGroups(result, [
      { claimIds: ['M-1', 'M-2', 'M-3'], patientRef: 'P-010', serviceDate: '2024-04-15', procedureCode: '99213', amount: 55.50 }
    ]);
    assert.ok(result.groups[0].claimIds.indexOf('U-1') === -1);
    assert.ok(result.groups[0].claimIds.indexOf('U-2') === -1);
  });

  test('returns an empty group list for an empty batch', function () {
    assert.deepEqual(code.findDuplicateGroups([]), { groups: [] });
  });

  test('returns two groups when amount 0 matches amount 0 and amount 1 matches amount 1', function () {
    var result = code.findDuplicateGroups([
      { claimId: 'Z-1', patientRef: 'P-SAME', serviceDate: '2024-01-15', procedureCode: '99213', amount: 0 },
      { claimId: 'Z-2', patientRef: 'P-SAME', serviceDate: '2024-01-15', procedureCode: '99213', amount: 0 },
      { claimId: 'O-1', patientRef: 'P-SAME', serviceDate: '2024-01-15', procedureCode: '99213', amount: 1 },
      { claimId: 'O-2', patientRef: 'P-SAME', serviceDate: '2024-01-15', procedureCode: '99213', amount: 1 }
    ]);
    expectGroups(result, [
      { claimIds: ['Z-1', 'Z-2'], patientRef: 'P-SAME', serviceDate: '2024-01-15', procedureCode: '99213', amount: 0 },
      { claimIds: ['O-1', 'O-2'], patientRef: 'P-SAME', serviceDate: '2024-01-15', procedureCode: '99213', amount: 1 }
    ]);
  });

  test('returns no groups when each pair differs in exactly one compared field', function () {
    var result = code.findDuplicateGroups([
      { claimId: 'A1', patientRef: 'P-100', serviceDate: '2024-05-10', procedureCode: '11111', amount: 10.00 },
      { claimId: 'A2', patientRef: 'P-1000', serviceDate: '2024-05-10', procedureCode: '11111', amount: 10.00 },
      { claimId: 'B1', patientRef: 'P-200', serviceDate: '2024-06-11', procedureCode: '99213', amount: 20.00 },
      { claimId: 'B2', patientRef: 'P-200', serviceDate: '2024-06-11', procedureCode: '99214', amount: 20.00 },
      { claimId: 'C1', patientRef: 'P-300', serviceDate: '2024-07-12', procedureCode: '33333', amount: 120.00 },
      { claimId: 'C2', patientRef: 'P-300', serviceDate: '2024-07-12', procedureCode: '33333', amount: 120.01 },
      { claimId: 'D1', patientRef: 'P-400', serviceDate: '2024-08-13', procedureCode: '44444', amount: 120.00 },
      { claimId: 'D2', patientRef: 'P-400', serviceDate: '2024-08-13', procedureCode: '44444', amount: 119.99 },
      { claimId: 'E1', patientRef: 'P-500', serviceDate: '2024-09-15', procedureCode: '55555', amount: 50.00 },
      { claimId: 'E2', patientRef: 'P-500', serviceDate: '2024-09-16', procedureCode: '55555', amount: 50.00 },
      { claimId: 'F1', patientRef: 'P-600', serviceDate: '2024-10-15', procedureCode: '66666', amount: 60.00 },
      { claimId: 'F2', patientRef: 'P-600', serviceDate: '2024-10-14', procedureCode: '66666', amount: 60.00 },
      { claimId: 'G1', patientRef: 'P-700', serviceDate: '2024-11-20', procedureCode: '77777', amount: 70.00 },
      { claimId: 'G2', patientRef: 'p-700', serviceDate: '2024-11-20', procedureCode: '77777', amount: 70.00 }
    ]);
    assert.deepEqual(result, { groups: [] });
  });

  test('flags the two leap day claims and not the claims one day before or after', function () {
    var result = code.findDuplicateGroups([
      { claimId: 'LD1', patientRef: 'P-L', serviceDate: '2024-02-29', procedureCode: '99213', amount: 11 },
      { claimId: 'LD2', patientRef: 'P-L', serviceDate: '2024-02-29', procedureCode: '99213', amount: 11 },
      { claimId: 'LD0', patientRef: 'P-L', serviceDate: '2024-02-28', procedureCode: '99213', amount: 11 },
      { claimId: 'LD3', patientRef: 'P-L', serviceDate: '2024-03-01', procedureCode: '99213', amount: 11 }
    ]);
    expectGroups(result, [
      { claimIds: ['LD1', 'LD2'], patientRef: 'P-L', serviceDate: '2024-02-29', procedureCode: '99213', amount: 11 }
    ]);
  });

  test('returns two groups for March 1 and March 31 and omits the neighboring days', function () {
    var result = code.findDuplicateGroups([
      { claimId: 'F1', patientRef: 'P-F', serviceDate: '2024-03-01', procedureCode: '99213', amount: 22 },
      { claimId: 'F2', patientRef: 'P-F', serviceDate: '2024-03-01', procedureCode: '99213', amount: 22 },
      { claimId: 'L1', patientRef: 'P-F', serviceDate: '2024-03-31', procedureCode: '99213', amount: 22 },
      { claimId: 'L2', patientRef: 'P-F', serviceDate: '2024-03-31', procedureCode: '99213', amount: 22 },
      { claimId: 'L0', patientRef: 'P-F', serviceDate: '2024-03-30', procedureCode: '99213', amount: 22 },
      { claimId: 'N1', patientRef: 'P-F', serviceDate: '2024-04-01', procedureCode: '99213', amount: 22 }
    ]);
    expectGroups(result, [
      { claimIds: ['F1', 'F2'], patientRef: 'P-F', serviceDate: '2024-03-01', procedureCode: '99213', amount: 22 },
      { claimIds: ['L1', 'L2'], patientRef: 'P-F', serviceDate: '2024-03-31', procedureCode: '99213', amount: 22 }
    ]);
  });

  test('returns five exact groups and does not merge dates across month or year boundaries', function () {
    var result = code.findDuplicateGroups([
      { claimId: 'JA1', patientRef: 'P-J', serviceDate: '2024-01-01', procedureCode: '99213', amount: 44 },
      { claimId: 'JA2', patientRef: 'P-J', serviceDate: '2024-01-01', procedureCode: '99213', amount: 44 },
      { claimId: 'JN1', patientRef: 'P-JN', serviceDate: '2024-01-31', procedureCode: '99213', amount: 55 },
      { claimId: 'JN2', patientRef: 'P-JN', serviceDate: '2024-01-31', procedureCode: '99213', amount: 55 },
      { claimId: 'JN0', patientRef: 'P-JN', serviceDate: '2024-01-30', procedureCode: '99213', amount: 55 },
      { claimId: 'JN3', patientRef: 'P-JN', serviceDate: '2024-02-01', procedureCode: '99213', amount: 55 },
      { claimId: 'DE1', patientRef: 'P-D1', serviceDate: '2024-12-01', procedureCode: '99213', amount: 66 },
      { claimId: 'DE2', patientRef: 'P-D1', serviceDate: '2024-12-01', procedureCode: '99213', amount: 66 },
      { claimId: 'DE0', patientRef: 'P-D1', serviceDate: '2024-11-30', procedureCode: '99213', amount: 66 },
      { claimId: 'DE3', patientRef: 'P-D1', serviceDate: '2024-12-02', procedureCode: '99213', amount: 66 },
      { claimId: 'D1', patientRef: 'P-Y', serviceDate: '2024-12-31', procedureCode: '99213', amount: 33 },
      { claimId: 'D2', patientRef: 'P-Y', serviceDate: '2024-12-31', procedureCode: '99213', amount: 33 },
      { claimId: 'D0', patientRef: 'P-Y', serviceDate: '2024-12-30', procedureCode: '99213', amount: 33 },
      { claimId: 'J1', patientRef: 'P-Y', serviceDate: '2025-01-01', procedureCode: '99213', amount: 33 },
      { claimId: 'J2', patientRef: 'P-Y', serviceDate: '2025-01-01', procedureCode: '99213', amount: 33 },
      { claimId: 'J3', patientRef: 'P-Y', serviceDate: '2025-01-02', procedureCode: '99213', amount: 33 }
    ]);
    expectGroups(result, [
      { claimIds: ['JA1', 'JA2'], patientRef: 'P-J', serviceDate: '2024-01-01', procedureCode: '99213', amount: 44 },
      { claimIds: ['JN1', 'JN2'], patientRef: 'P-JN', serviceDate: '2024-01-31', procedureCode: '99213', amount: 55 },
      { claimIds: ['DE1', 'DE2'], patientRef: 'P-D1', serviceDate: '2024-12-01', procedureCode: '99213', amount: 66 },
      { claimIds: ['D1', 'D2'], patientRef: 'P-Y', serviceDate: '2024-12-31', procedureCode: '99213', amount: 33 },
      { claimIds: ['J1', 'J2'], patientRef: 'P-Y', serviceDate: '2025-01-01', procedureCode: '99213', amount: 33 }
    ]);
  });

  test('throws unknown field for an extra field in the first middle or last claim and does not return a group', function () {
    function capture(claims) {
      var returned = null;
      var thrown = null;
      try {
        returned = code.findDuplicateGroups(claims);
      } catch (err) {
        thrown = err;
      }
      return { returned: returned, thrown: thrown };
    }
    var call1 = capture([
      { claimId: 'X-1', patientRef: 'P-001', serviceDate: '2024-03-05', procedureCode: '99213', amount: 120.00, priority: 'yes' }
    ]);
    assert.ok(call1.thrown instanceof Error);
    assert.equal(call1.thrown.message, 'unknown field: priority');
    assert.equal(call1.returned, null);
    var call2 = capture([
      { claimId: 'Y-1', patientRef: 'P-002', serviceDate: '2024-03-05', procedureCode: '99213', amount: 80.00 },
      { claimId: 'Y-2', patientRef: 'P-002', serviceDate: '2024-03-05', procedureCode: '99213', amount: 80.00, source: 'yes' },
      { claimId: 'Y-3', patientRef: 'P-002', serviceDate: '2024-03-05', procedureCode: '99213', amount: 80.00 }
    ]);
    assert.ok(call2.thrown instanceof Error);
    assert.equal(call2.thrown.message, 'unknown field: source');
    assert.equal(call2.returned, null);
    var call3 = capture([
      { claimId: 'E-1', patientRef: 'P-001', serviceDate: '2024-03-05', procedureCode: '99213', amount: 120.00 },
      { claimId: 'E-2', patientRef: 'P-001', serviceDate: '2024-03-05', procedureCode: '99213', amount: 120.00 },
      { claimId: 'E-3', patientRef: 'P-001', serviceDate: '2024-03-05', procedureCode: '99213', amount: 120.00, priority: 'yes' }
    ]);
    assert.ok(call3.thrown instanceof Error);
    assert.equal(call3.thrown.message, 'unknown field: priority');
    assert.equal(call3.returned, null);
  });

  test('groups claims whose amounts are 120 and 120.00 as the same number', function () {
    var result = code.findDuplicateGroups([
      { claimId: 'N-1', patientRef: 'P-N', serviceDate: '2024-11-11', procedureCode: '99213', amount: 120 },
      { claimId: 'N-2', patientRef: 'P-N', serviceDate: '2024-11-11', procedureCode: '99213', amount: 120.00 }
    ]);
    expectGroups(result, [
      { claimIds: ['N-1', 'N-2'], patientRef: 'P-N', serviceDate: '2024-11-11', procedureCode: '99213', amount: 120 }
    ]);
  });
})();
